import React, {useState, useEffect} from "react";

function AnswerComponent() {
	const [answerList, setAnswerList] = useState([]);

	const putAnswer = (value) => {
		setAnswerList((prevItem) => {
			const newItems = prevItem.includes(value)
				? prevItem.filter((i) => i !== value) // 제거
				: [...prevItem, value]; // 추가

			console.log("즉시 변경된 리스트:", newItems); // 변경된 값 즉시 확인
			return newItems;
		});
	};

	useEffect(() => {
		console.log("렌더링 후 현재 리스트:", answerList);
	}, [answerList]); // answerList가 변경될 때마다 실행

	return (
		<div>
			<button onClick={() => putAnswer("A")}>A</button>
			<button onClick={() => putAnswer("B")}>B</button>
			<button onClick={() => putAnswer("C")}>C</button>

			<h3>선택된 답변:</h3>
			<ul>
				{answerList.map((item, index) => (
					<li key={index}>{item}</li>
				))}
			</ul>
		</div>
	);
}

export default AnswerComponent;
